  const refs = stationData.length &gt; 0 ? stationData[0] : {HPMS_AADT: 0, MODEL_VOL: 0, HAS_MODEL_DATA: false};
  const stationHasData = stationData.length &gt; 0;

  // Tue/Wed/Thu average within the calibration period -- the subset of days
  // typically used as the "representative weekday" ground truth for
  // calibration, since it excludes weekend and Mon/Fri shoulder effects.
  const calStart = new Date("2023-09-01");
  const calEnd = new Date("2023-11-15");
  const calTueThuRows = stationData.filter(d =&gt; {
    const dow = d.Date.getDay();
