    ClassLabel: classLabels.get(d.FTCLASS) ?? d.FTCLASS,
    VMT_Mod: d.VMT_Mod,
    VMT_Target: d.VMT_Target
  }));

  const totals = new Map(); // `${CO_FIPS}|${vehType}` -&gt; summed VMT_Mod/VMT_Target
  for (const d of vmtGroupRows) {
    const key = `${d.CO_FIPS}|${d.vehType}`;
    const t = totals.get(key) ?? {CO_FIPS: d.CO_FIPS, vehType: d.vehType, VMT_Mod: 0, VMT_Target: 0};
    t.VMT_Mod += d.VMT_Mod;
    t.VMT_Target += d.VMT_Target;
    totals.set(key, t);
  }
  for (const t of totals.values()) {
    rows.push({
      County: countyNames.get(t.CO_FIPS),
      VehLabel: chartVehLabels.get(t.vehType),
      ClassLabel: 'All Roadways',
      VMT_Mod: t.VMT_Mod,
      VMT_Target: t.VMT_Target
    });
  }

  return rows.map(d =&gt; ({
    ...d,
    ModelM: d.VMT_Mod / 1e6,
    TargetM: d.VMT_Target / 1e6,
    vmtDiff: d.VMT_Mod - d.VMT_Target,
    vmtDiffPct: d.VMT_Target ? (d.VMT_Mod - d.VMT_Target) / d.VMT_Target : undefined
  }));
}


























































