function vmtDumbbellChart(vehLabel, data) {
  // Explicit [0, max] domain -- Plot's auto domain would otherwise start
  // near the smallest value, exaggerating Model-vs-Target gaps visually.
  const xMax = d3.max(data, d =&gt; Math.max(d.ModelM, d.TargetM)) || 1;
  const chart = Plot.plot({
    width: width,
    height: 120,
    marginLeft: 140,
    marginRight: 60,
    marginTop: 12,
    y: {domain: chartCountyOrder, label: null},
    x: {label: "Total Daily VMT (millions)", domain: [0, xMax], grid: true, nice: true},
    marks: [
      Plot.link(data, {
        x1: "ModelM", x2: "TargetM", y: "County",
        stroke: themeLinkGrey, strokeWidth: 3
      }),
      // Target drawn first, Model second, so the Model ring always sits on
      // top where the two dots overlap.
      Plot.dot(data, {
        x: "TargetM", y: "County", fill: themeTarget, r: 10,
        title: d =&gt; `${d.County} — ${d.VehLabel} — ${d.ClassLabel}\nTarget: ${d3.format(",.2f")(d.TargetM)}M VMT`
      }),
      Plot.dot(data, {
        x: "ModelM", y: "County", fill: themeModel, r: 8,
        title: d =&gt; `${d.County} — ${d.VehLabel} — ${d.ClassLabel}\nModel: ${d3.format(",.2f")(d.ModelM)}M VMT`
      }),
      // dx/textAnchor are constant style options on Plot's text mark, not
      // per-datum channels -- a function there silently collapses to dx=0 /
      // textAnchor="middle" instead of flipping per point. Split into two
      // marks (one per side) so each gets a real constant.
      Plot.text(data.filter(d =&gt; d.ModelM &gt;= d.TargetM), {
        x: "ModelM", y: "County",
        text: d =&gt; d3.format("+.1%")(d.vmtDiffPct),
        dx: 8, textAnchor: "start",
        fontSize: 13, fontWeight: 600,
        fill: d =&gt; Math.abs(d.vmtDiffPct) &gt; 0.1 ? themeDanger : themeNeutral
      }),
      Plot.text(data.filter(d =&gt; d.ModelM &lt; d.TargetM), {
        x: "ModelM", y: "County",
        text: d =&gt; d3.format("+.1%")(d.vmtDiffPct),
        dx: -8, textAnchor: "end",
        fontSize: 13, fontWeight: 600,
        fill: d =&gt; Math.abs(d.vmtDiffPct) &gt; 0.1 ? themeDanger : themeNeutral
      })
    ]
  });
  return html`&lt;div&gt;
    &lt;div style="font-size: 18px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; color: ${themeNeutral};"&gt;${vehLabel}&lt;/div&gt;
    ${chart}
  &lt;/div&gt;`;
}

