    &lt;/li&gt;`)}
  &lt;/ul&gt;
  &lt;div class="tab-content"&gt;
    ${classes.map(cls =&gt; html`&lt;div id="${vmtClassTabId(cls)}" class="tab-pane${cls === vmtActiveTab ? " active" : ""}" role="tabpanel" aria-labelledby="${vmtClassTabId(cls)}-tab" style="padding-top: 16px;"&gt;
      &lt;ul class="nav nav-tabs" role="tablist"&gt;
