        ${vmtVehTabNames.map(vt =&gt; html`&lt;div id="${vmtVehTabId(cls, vt)}" class="tab-pane${vt === vmtActiveVehTab ? " active" : ""}" role="tabpanel" aria-labelledby="${vmtVehTabId(cls, vt)}-tab" style="padding-top: 16px;"&gt;
