        &lt;/div&gt;`)}
      &lt;/div&gt;
    &lt;/div&gt;`)}
  &lt;/div&gt;
&lt;/div&gt;`;

  // Bootstrap's own tab.js toggles the active classes on click; this just
  // mirrors that choice into the mutables so the next re-render remembers
  // it. One listener covers both tab levels -- it matches the clicked
  // link's id against every possible class/vehTab id pair rather than
  // relying on DOM order (which differs between the two levels).
  root.querySelectorAll('a[data-bs-toggle="tab"]').forEach(tabLink =&gt; {
    tabLink.addEventListener("shown.bs.tab", () =&gt; {
      const cls = classes.find(c =&gt; tabLink.id === `${vmtClassTabId(c)}-tab`);
      if (cls !== undefined) {
        mutable vmtActiveTab = cls;
        return;
      }
      for (const c of classes) {
        for (const vt of vmtVehTabNames) {
          if (tabLink.id === `${vmtVehTabId(c, vt)}-tab`) {
            mutable vmtActiveVehTab = vt;
            return;
          }
        }
      }
    });
  });

  return root;
}












