        : [-5000, -1500, -500, 500, 1500, 5000];
      colors = [
        "#2166ac", "#4393c3", "#92c5de", // Blues
        "#f7f7f7",                       // Neutral
        "#f4a582", "#d6604d", "#b2182b"  // Reds
      ];
  }

  // Generic over bins.length so it works for either the 8-breakpoint
  // percent scale or the 6-breakpoint absolute scale.
  const getColor = (val) =&gt; {
    for (let i = 0; i &lt; bins.length; i++) {
      if (val &lt; bins[i]) return colors[i];
    }
    return colors[bins.length];
  };

  const container = document.createElement("div");
  container.style.height = "600px";
  container.style.width = "100%";
  const map = LM.map(container).setView(vmtMapViewState.center, vmtMapViewState.zoom);
