  });

  LM.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
    attribution: '&copy; OpenStreetMap &copy; CARTO',
    maxZoom: 19
  }).addTo(map);

  // GeoJSON Layer -- vol_diff_geojson carries every calib_run's features
  // together (one polyline per SEGID per run), so filter to the selected
