normalizeScreenlineIdJs = value =&gt; {
  if (value == null) return ""
  const text = String(value).trim()
  const num = Number(text)
  return Number.isFinite(num) ? num.toFixed(2) : text
}

screenlineStatsMap = new Map(screenline_filtered.map(d =&gt; [String(d.ScreenlineKey), d]))

screenlineColor = pct =&gt; {
  if (!Number.isFinite(pct)) return "#7f8c8d"
  if (pct &gt;= 0.2) return "#b2182b"
  if (pct &gt;= 0.1) return "#d6604d"
  if (pct &gt; 0.02) return "#f4a582"
  if (pct &lt;= -0.2) return "#2166ac"
  if (pct &lt;= -0.1) return "#4393c3"
  if (pct &lt; -0.02) return "#92c5de"
  return "#7fbf7b"
}

