regionTimeSummary = {
  const periodLabels = new Map([['AM', 'AM Peak'], ['MD', 'Midday'], ['PM', 'PM Peak'], ['EV', 'Evening'], ['ALL', 'All Day']]);
  return Array.from(periodLabels, ([code, label]) =&gt; {
    // "All Day" pools rows across every period instead of filtering to one.
    const rows = timeT.filter(d =&gt; d.calib_run === globalCalibRun && (code === 'ALL' || d.Period === code) && Number.isFinite(d.spdObs) && Number.isFinite(d.spdMod));
    const obsMean = d3.mean(rows, d =&gt; d.spdObs);
    const modMean = d3.mean(rows, d =&gt; d.spdMod);
    return {
      Period: label,
      obsMean, modMean,
      diff: modMean - obsMean,
      diffPct: obsMean ? (modMean - obsMean) / obsMean : undefined
    };
  });
}

