transitGridBreakpoint = 700
transitGridGap = 24

function transitDumbbellChart(category, data) {
  const isRatio = category === "Transfer Ratio";
  const fmtVal = isRatio ? d3.format(",.2f") : d3.format(",.0f");
  const xLabel = isRatio ? "Transfer Ratio" : (category.startsWith("Trips") ? "Daily Trips" : "Daily Boardings");
  const xMax = d3.max(data, d =&gt; Math.max(d.Model, d.Target)) || 1;
  // Chart sits in one cell of the 2x2 grid (transit-dumbbell-grid below) --
  // account for the cell being half the container width above the grid's
  // breakpoint, and full width once the grid collapses to one column, so the
  // plotted width matches what CSS actually gives this chart.
  const chartWidth = width &lt; transitGridBreakpoint ? width : (width - transitGridGap) / 2;

  const chart = Plot.plot({
    width: chartWidth,
    height: 260,
    marginLeft: 110,
    marginRight: 60,
    marginTop: 12,
    y: {domain: transitModeOrder, label: null},
    x: {label: xLabel, domain: [0, xMax], grid: true, nice: true},
    marks: [
      Plot.link(data, {
        x1: "Model", x2: "Target", y: "Mode",
        stroke: themeLinkGrey, strokeWidth: 3
      }),
      // Target drawn first, Model second, so the Model ring always sits on
      // top where the two dots overlap.
      Plot.dot(data, {
        x: "Target", y: "Mode", fill: themeTarget, r: 10,
        title: d =&gt; `${d.Mode}\nTarget: ${fmtVal(d.Target)}`
      }),
      Plot.dot(data, {
        x: "Model", y: "Mode", fill: themeModel, r: 8,
        title: d =&gt; `${d.Mode}\nModel: ${fmtVal(d.Model)}`
      }),
      Plot.text(data.filter(d =&gt; d.Model &gt;= d.Target), {
        x: "Model", y: "Mode",
        text: d =&gt; d3.format("+.1%")(d["% Difference"]),
        dx: 8, textAnchor: "start",
        fontSize: 13, fontWeight: 600,
        fill: d =&gt; Math.abs(d["% Difference"]) &gt; 0.1 ? themeDanger : themeNeutral
      }),
      Plot.text(data.filter(d =&gt; d.Model &lt; d.Target), {
        x: "Model", y: "Mode",
        text: d =&gt; d3.format("+.1%")(d["% Difference"]),
        dx: -8, textAnchor: "end",
        fontSize: 13, fontWeight: 600,
        fill: d =&gt; Math.abs(d["% Difference"]) &gt; 0.1 ? themeDanger : themeNeutral
      })
    ]
  });
  return html`&lt;div&gt;${chart}&lt;/div&gt;`;
}

// Per-category table (Mode, Model, Target, Difference, plus an "All" total
// row) shown directly beneath its own chart, rather than one shared
// all-categories table off to the side.
function transitCategoryTable(category, data) {
  const fmt = category === "Transfer Ratio" ? d3.format(",.2f") : d3.format(",.0f");
  const totalRow = dataBTT.find(d =&gt; d.Title === category && d.calib_run === globalCalibRun && d.Mode === "All");
  const rows = [...data, totalRow].filter(d =&gt; d);

  return html`&lt;table style="width:100%; border-collapse:collapse; font-size: 12.5px; margin-top: 6px;"&gt;
    &lt;thead&gt;
      &lt;tr&gt;
        &lt;th style="text-align:left; padding:4px 6px; border-bottom:2px solid #999;"&gt;Mode&lt;/th&gt;
        &lt;th style="text-align:right; padding:4px 6px; border-bottom:2px solid #999;"&gt;Model&lt;/th&gt;
        &lt;th style="text-align:right; padding:4px 6px; border-bottom:2px solid #999;"&gt;Target&lt;/th&gt;
        &lt;th style="text-align:right; padding:4px 6px; border-bottom:2px solid #999;"&gt;Difference&lt;/th&gt;
      &lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;
      ${rows.map(d =&gt; {
        const isTotal = d.Mode === "All";
        const cellStyle = isTotal ? "padding: 3px 6px; border-top: 1px solid #ccc; font-weight:600;" : "padding: 3px 6px;";
        return html`&lt;tr&gt;
          &lt;td style="${cellStyle}"&gt;${isTotal ? "Total" : d.Mode}&lt;/td&gt;
          &lt;td style="${cellStyle} text-align:right;"&gt;${fmt(d.Model)}&lt;/td&gt;
          &lt;td style="${cellStyle} text-align:right;"&gt;${fmt(d.Target)}&lt;/td&gt;
          &lt;td style="${cellStyle} text-align:right;"&gt;${d3.format("+.1%")(d["% Difference"])}&lt;/td&gt;
        &lt;/tr&gt;`;
      })}
    &lt;/tbody&gt;
  &lt;/table&gt;`;
}

