crtFiltered = crtData.filter(d =&gt;
  d.calib_run === globalCalibRun &&
  (_periodCode === null || d.Period     === _periodCode) &&
  (_accessCode === null || d.AccessMode === _accessCode)
)

// ── 2. Build histogram bins for each Source ──────────────────────────────────
crtBinned = {
  const rawMax = d3.max(crtFiltered, d =&gt; d.Distance);
  const maxDist = rawMax ? Math.ceil(rawMax / crtBinSize) * crtBinSize : 120;
  const thresholds = d3.range(0, maxDist + crtBinSize, crtBinSize);

  const rows = [];
  for (const source of ["Target", "Modeled"]) {
    const src = crtFiltered.filter(d =&gt; d.Source === source);
    const totalTrips = d3.sum(src, d =&gt; d.Trips);

    for (let i = 0; i &lt; thresholds.length - 1; i++) {
      const lo = thresholds[i];
      const hi = thresholds[i + 1];
      const trips = d3.sum(
        src.filter(d =&gt; d.Distance &gt;= lo && d.Distance &lt; hi),
        d =&gt; d.Trips
      );
      rows.push({
        BinLo  : lo,
        BinHi  : hi,
        BinMid : (lo + hi) / 2,
        Trips  : trips,
        Share  : totalTrips &gt; 0 ? trips / totalTrips : 0,
        Source : source,
      });
    }
  }
  return rows;
}






























